          ))}
        </div>

{/* BINGO BOOK SETTINGS PANEL */}
        <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-6 mb-8 shadow-lg">
          <div className="flex items-center gap-3 mb-6 border-b border-zinc-800 pb-4">
