              className={`w-full py-4 font-black uppercase tracking-widest rounded-xl transition-all ${
                isFree ? 'bg-zinc-800 text-zinc-500 cursor-not-allowed' : 'bg-zinc-800 text-white hover:bg-zinc-700 cursor-pointer'
