                      className="w-full bg-black border border-[#fe9a00]/30 text-[#fe9a00] rounded p-2 text-[10px] font-bold uppercase tracking-widest"
                      onChange={(e) => handleAutofillCreator(i, e.target.value)}
                      value=""
                    >
