                        </select>

                        {(isCustomFlag || selectValue === 'OTHER') && (
                          <input 
                            type="text" 
                            placeholder="Code" 
                            maxLength={2}
                            value={c.flagCode} 
                            onChange={(e) => { 
                              const nc = [...formData.creators]; 
                              nc[i].flagCode = e.target.value.toUpperCase(); 
                              handleInputChange('creators', nc); 
                            }} 
